import { BaseEntity } from 'src/common/entities/base.entity';
import { ChatId } from 'src/common/types/brands.type';
import { Column, Entity, ManyToOne, RelationId } from 'typeorm';
import { Chat } from './chat.entity';

@Entity('link')
export class Link extends BaseEntity {
    /** 22-char base64url code generated by the server (crypto.randomBytes(16)). */
    @Column({ unique: true, length: 32 })
    code: string;

    @ManyToOne(() => Chat, { onDelete: 'CASCADE' })
    chat: Chat;

    /** Computed FK value (no extra column) — used by the wire serializer. */
    @RelationId((link: Link) => link.chat)
    chatId: ChatId;

    /** Who created the link; null for legacy rows created before this column. */
    @Column({ type: 'bigint', nullable: true })
    createdByUserId: string | number | null;

    /**
     * Legacy limit column, kept for old rows/clients. New links mirror
     * `maxUses` here (0 = unlimited) so old readers stay consistent.
     */
    @Column({ type: 'int', default: 0 })
    usageLimit: number;

    /** Legacy counter, kept in sync with `usesCount` on every join. */
    @Column({ type: 'int', default: 0 })
    usageCount: number;

    /** Null = unlimited uses. */
    @Column({ type: 'int', nullable: true })
    maxUses: number | null;

    /** Number of NEW members admitted through this link. */
    @Column({ type: 'int', default: 0 })
    usesCount: number;

    /** Null = never expires. */
    @Column({ type: 'timestamptz', nullable: true })
    expiresAt: Date | null;

    /** Set together with `isActive = false` when the link is revoked. */
    @Column({ type: 'timestamptz', nullable: true })
    revokedAt: Date | null;

    /** Legacy active flag; kept consistent with `revokedAt`. */
    @Column({ default: true })
    isActive: boolean;
}
